from typing import List


def all_prefixes(string: str) -> List[str]:
    """ 返回输入字符串中最长的前缀列表，从小到大排序。"""
    if not string:
        return []
    prefix = []
    for i in range(1, len(string) + 1):
        prefix.append(string[:i])
    return sorted(prefix)
