from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Count the frequency of each character in the string
    char_count = Counter(test)

    # Find the character with the highest frequency and its count
    most_common_char = max(char_count.items(), key=lambda x: x[1])

    # Return the character and its count as a dictionary
    return {"character": most_common_char[0], "count": most_common_char[1]}
