import numpy as np

def max_fill(grid, capacity):
    if not grid or not grid[0]:
        return 0

    row = grid[0].count(1)
    col = len(grid[0])

    # Initialize the grid with zeros
    grid = np.zeros((row, col), dtype=int)

    # Fill the grid with water
    for i in range(row):
        for j in range(col):
            if grid[i][j] == 1:
                grid[i][j] = 0
                grid[i][j] += capacity

    # Find the number of times buckets need to be lowered
    num_lowered = 0
    for i in range(row):
        for j in range(col):
            if grid[i][j] == 0:
                num_lowered += 1
            elif grid[i][j] != 0:
                break

    return num_lowered

# Example usage
grid = [[0,0,1,0], [0,1,0,0], [1,1,1,1]]
bucket_capacity = 1
print(max_fill(grid, bucket_capacity))  # Output: 6
