def is_nested(string):
    def is_balanced(substring):
        balance = 0
        for char in substring:
            if char == '[':
                balance += 1
            elif char == ']':
                balance -= 1
            if balance < 0:  # A closing bracket must have a corresponding opening bracket
                return False
        return balance == 0  # The string is balanced if all opening brackets have a corresponding closing bracket

    for i in range(len(string) - 1):
        if is_balanced(string[i:i+2]) and is_balanced(string[i+2:]):
            return True
    return False
