def can_arrange(arr):
    if len(arr) == 0:
        return -1

    max_index = -1
    for i in range(len(arr) - 1):
        if arr[i] >= arr[i + 1]:
            max_index = i
            break

    if max_index == -1:
        return -1

    for i in range(len(arr) - 1):
        if arr[i] >= arr[i + 1]:
            max_index = i
            break

    for i in range(len(arr) - 1):
        if arr[i] >= arr[i + 1]:
            max_index = i
            break

    return max_index
