def solve(s):
    # Filter out non-letter characters and convert to lowercase
    filtered_chars = [char.lower() for char in s if char.isalpha()]

    # If no letters are present, reverse the string
    if not filtered_chars:
        return s[::-1]

    # If there are letters, reverse the case of each letter
    return ''.join([char.upper() if char.islower() else char.lower() for char in filtered_chars])
